import unittest
from pathlib import Path
from pylint.testutils._primer.package_to_lint import PackageToLint

class TestPathsToLint(unittest.TestCase):

    def test_paths_to_lint_with_multiple_directories(self):
        """Test paths_to_lint with multiple directories."""
        package = PackageToLint(
            url="https://github.com/test/repo",
            branch="main",
            directories=["src", "tests", "docs"],
            commit=None
        )
        # Access the private attribute directly since it's a property without setter
        package._clone_directory = Path("/tmp/test_repo")

        result = package.paths_to_lint()

        expected = [
            "/tmp/test_repo/src",
            "/tmp/test_repo/tests", 
            "/tmp/test_repo/docs"
        ]
        self.assertEqual(result, expected)
        self.assertEqual(len(result), len(package.directories))

    def test_paths_to_lint_with_single_directory(self):
        """Test paths_to_lint with a single directory."""
        package = PackageToLint(
            url="https://github.com/test/repo",
            branch="main",
            directories=["src"],
            commit=None
        )
        package._clone_directory = Path("/tmp/test_repo")

        result = package.paths_to_lint()

        expected = ["/tmp/test_repo/src"]
        self.assertEqual(result, expected)
        self.assertEqual(len(result), 1)

    def test_paths_to_lint_with_empty_directories(self):
        """Test paths_to_lint with empty directories list."""
        package = PackageToLint(
            url="https://github.com/test/repo",
            branch="main",
            directories=[],
            commit=None
        )
        package._clone_directory = Path("/tmp/test_repo")

        result = package.paths_to_lint()

        self.assertEqual(result, [])
        self.assertEqual(len(result), 0)

    def test_paths_to_lint_with_nested_directories(self):
        """Test paths_to_lint with nested directory paths."""
        package = PackageToLint(
            url="https://github.com/test/repo",
            branch="main",
            directories=["src/utils/helpers", "tests/integration/api"],
            commit=None
        )
        package._clone_directory = Path("/tmp/test_repo")

        result = package.paths_to_lint()

        expected = [
            "/tmp/test_repo/src/utils/helpers",
            "/tmp/test_repo/tests/integration/api"
        ]
        self.assertEqual(result, expected)

    def test_paths_to_lint_preserves_instance_state(self):
        """Test that paths_to_lint doesn't modify the instance state."""
        package = PackageToLint(
            url="https://github.com/test/repo",
            branch="main",
            directories=["src", "tests"],
            commit=None
        )
        package._clone_directory = Path("/tmp/test_repo")

        # Store original state
        original_directories = package.directories.copy()
        original_clone_directory = package._clone_directory

        result = package.paths_to_lint()

        # Verify state is unchanged
        self.assertEqual(package.directories, original_directories)
        self.assertEqual(package._clone_directory, original_clone_directory)
        self.assertIsInstance(result, list)

    def test_paths_to_lint_with_absolute_clone_directory(self):
        """Test paths_to_lint with absolute clone directory path."""
        package = PackageToLint(
            url="https://github.com/test/repo",
            branch="main",
            directories=["module1", "module2"],
            commit=None
        )
        package._clone_directory = Path("/home/user/projects/test_repo")

        result = package.paths_to_lint()

        expected = [
            "/home/user/projects/test_repo/module1",
            "/home/user/projects/test_repo/module2"
        ]
        self.assertEqual(result, expected)

