class TestVisitFunctiondef(unittest.TestCase):

    def setUp(self):
        self.checker = BasicErrorChecker()

    def create_function_node(self, name="__main__", args=None, body=None):
        """Helper to create a FunctionDef node."""
        if args is None:
            args = []
        if body is None:
            body = []
        func_node = nodes.FunctionDef()
        func_node.name = name
        func_node.args = Mock()
        func_node.args.args = [Mock(arg=arg) for arg in args]
        func_node.body = body
        return func_node

    @patch.object(BasicErrorChecker, 'add_message')
    def test_duplicate_argument_names(self, mock_add_message):
        # Create a function with duplicate argument names
        node = self.create_function_node(args=["a", "b", "a"])
        self.checker.visit_functiondef(node)
        mock_add_message.assert_called_with(
            "duplicate-argument-name", node=node.args.args[2], args=("a",)
        )

    @patch.object(BasicErrorChecker, 'add_message')
    def test_init_method_is_generator(self, mock_add_message):
        # Create an __init__ method with a yield (making it a generator)
        yield_node = nodes.Yield()
        node = self.create_function_node(name="__init__", body=[yield_node])
        self.checker.visit_functiondef(node)
        mock_add_message.assert_called_with("init-is-generator", node=node)

    @patch.object(BasicErrorChecker, 'add_message')
    def test_explicit_return_in_init(self, mock_add_message):
        # Create an __init__ method with an explicit return value
        return_node = nodes.Return()
        return_node.value = nodes.Const(42)  # Non-None return
        node = self.create_function_node(name="__init__", body=[return_node])
        self.checker.visit_functiondef(node)
        mock_add_message.assert_called_with("return-in-init", node=return_node)

    @patch.object(BasicErrorChecker, 'add_message')
    def test_no_errors_normal_function(self, mock_add_message):
        # Normal function with no issues
        node = self.create_function_node(name="normal_func", args=["a", "b"])
        self.checker.visit_functiondef(node)
        mock_add_message.assert_not_called()

    @patch.object(BasicErrorChecker, 'add_message')
    def test_return_arg_in_generator_py33_or_earlier(self, mock_add_message):
        # Generator with return statement having a value (only error in Python < 3.4)
        with patch('sys.version_info', new=(3, 3)):
            return_node = nodes.Return()
            return_node.value = nodes.Const(42)
            yield_node = nodes.Yield()
            node = self.create_function_node(body=[yield_node, return_node])
            self.checker.visit_functiondef(node)
            mock_add_message.assert_called_with("return-arg-in-generator", node=return_node)

    @patch.object(BasicErrorChecker, 'add_message')
    def test_nonlocal_and_global_same_name(self, mock_add_message):
        # Create a function where a name is both nonlocal and global
        node = self.create_function_node()
        node.locals = {"x": [Mock()]}
        node.globals = {"x": [Mock()]}
        self.checker.visit_functiondef(node)
        mock_add_message.assert_called_with(
            "nonlocal-and-global", node=node, args=("x",)
        )

    @patch.object(BasicErrorChecker, 'add_message')
    def test_nonlocal_without_binding(self, mock_add_message):
        # Name declared nonlocal but not found in outer scopes
        node = self.create_function_node()
        node.locals = {}
        node.globals = {}
        node.nonlocals = {"y"}
        self.checker.visit_functiondef(node)
        mock_add_message.assert_called_with(
            "nonlocal-without-binding", node=node, args=("y",)
        )

    @patch.object(BasicErrorChecker, 'add_message')
    def test_used_prior_global_declaration(self, mock_add_message):
        # A name is used before being declared global (Python 3.6+)
        with patch('sys.version_info', new=(3, 6)):
            node = self.create_function_node()
            node.locals = {"z": [Mock()]}
            node.globals = {"z": [Mock()]}
            self.checker.visit_functiondef(node)
            mock_add_message.assert_called_with(
                "used-prior-global-declaration", node=node, args=("z",)
            )


