import unittest
from typing import Dict, Set
from pylint.graph import get_cycles

class TestGetCycles(unittest.TestCase):

    def test_empty_graph(self):
        """Test get_cycles with an empty graph."""
        graph_dict: Dict[str, Set[str]] = {}
        result = get_cycles(graph_dict)
        self.assertEqual(result, [])

    def test_single_vertex_no_edges(self):
        """Test get_cycles with a single vertex and no edges."""
        graph_dict = {"A": set()}
        result = get_cycles(graph_dict)
        self.assertEqual(result, [])

    def test_single_vertex_self_loop(self):
        """Test get_cycles with a single vertex having a self-loop."""
        graph_dict = {"A": {"A"}}
        result = get_cycles(graph_dict)
        self.assertEqual(len(result), 1)
        self.assertIn(["A"], result)

    def test_two_vertices_no_cycle(self):
        """Test get_cycles with two vertices and no cycle."""
        graph_dict = {"A": {"B"}, "B": set()}
        result = get_cycles(graph_dict)
        self.assertEqual(result, [])

    def test_two_vertices_cycle(self):
        """Test get_cycles with two vertices forming a cycle."""
        graph_dict = {"A": {"B"}, "B": {"A"}}
        result = get_cycles(graph_dict)
        self.assertEqual(len(result), 1)
        cycle = result[0]
        self.assertIn(cycle, [["A", "B"], ["B", "A"]])

    def test_linear_chain_no_cycle(self):
        """Test get_cycles with a linear chain of vertices."""
        graph_dict = {"A": {"B"}, "B": {"C"}, "C": {"D"}, "D": set()}
        result = get_cycles(graph_dict)
        self.assertEqual(result, [])

    def test_triangle_cycle(self):
        """Test get_cycles with a triangle cycle."""
        graph_dict = {"A": {"B"}, "B": {"C"}, "C": {"A"}}
        result = get_cycles(graph_dict)
        self.assertEqual(len(result), 1)
        cycle_set = set(result[0])
        expected_cycle_set = {"A", "B", "C"}
        self.assertEqual(cycle_set, expected_cycle_set)

    def test_multiple_cycles(self):
        """Test get_cycles with multiple separate cycles."""
        graph_dict = {
            "A": {"B"}, 
            "B": {"C"}, 
            "C": {"A"}, 
            "D": {"E"}, 
            "E": {"D"}
        }
        result = get_cycles(graph_dict)
        self.assertEqual(len(result), 2)

        # Check that we have both cycles
        cycles = [set(cycle) for cycle in result]
        expected_cycles = [{"A", "B", "C"}, {"D", "E"}]
        for expected in expected_cycles:
            self.assertIn(expected, cycles)

    def test_complex_graph_with_multiple_cycles(self):
        """Test get_cycles with a more complex graph containing multiple cycles."""
        graph_dict = {
            "A": {"B"},
            "B": {"C", "D"},
            "C": {"A"},
            "D": {"E"},
            "E": {"F"},
            "F": {"D"},
            "G": set()
        }
        result = get_cycles(graph_dict)
        self.assertEqual(len(result), 2)

        cycles = [set(cycle) for cycle in result]
        expected_cycles = [{"A", "B", "C"}, {"D", "E", "F"}]
        for expected in expected_cycles:
            self.assertIn(expected, cycles)

    def test_disconnected_components(self):
        """Test get_cycles with disconnected components."""
        graph_dict = {
            "A": {"B"},
            "B": {"C"},
            "C": set(),
            "D": {"E"},
            "E": {"F"},
            "F": {"D"}
        }
        result = get_cycles(graph_dict)
        self.assertEqual(len(result), 1)
        self.assertEqual(set(result[0]), {"D", "E", "F"})

    def test_specified_vertices_none(self):
        """Test get_cycles when vertices parameter is explicitly None."""
        graph_dict = {"A": {"B"}, "B": {"A"}}
        result = get_cycles(graph_dict, None)
        self.assertEqual(len(result), 1)
        cycle = result[0]
        self.assertIn(cycle, [["A", "B"], ["B", "A"]])

    def test_specified_vertices_subset(self):
        """Test get_cycles with a subset of vertices specified."""
        graph_dict = {
            "A": {"B"}, 
            "B": {"C"}, 
            "C": {"A"}, 
            "D": {"E"}, 
            "E": {"D"}
        }
        # Only check for cycles involving A, B, C
        result = get_cycles(graph_dict, ["A", "B", "C"])
        self.assertEqual(len(result), 1)
        self.assertEqual(set(result[0]), {"A", "B", "C"})

    def test_specified_vertices_no_cycles(self):
        """Test get_cycles with vertices that don't form cycles."""
        graph_dict = {
            "A": {"B"}, 
            "B": {"C"}, 
            "C": {"A"}, 
            "D": {"E"}, 
            "E": {"F"},
            "F": set()
        }
        # Only check for cycles involving D, E, F (no cycle there)
        result = get_cycles(graph_dict, ["D", "E", "F"])
        self.assertEqual(result, [])

    def test_specified_vertices_empty_list(self):
        """Test get_cycles with an empty vertices list."""
        graph_dict = {"A": {"B"}, "B": {"A"}}
        result = get_cycles(graph_dict, [])
        self.assertEqual(result, [])

    def test_tree_structure(self):
        """Test get_cycles with a tree structure (no cycles)."""
        graph_dict = {
            "Root": {"Child1", "Child2"},
            "Child1": {"Grandchild1", "Grandchild2"},
            "Child2": {"Grandchild3"},
            "Grandchild1": set(),
            "Grandchild2": set(),
            "Grandchild3": set()
        }
        result = get_cycles(graph_dict)
        self.assertEqual(result, [])

if __name__ == '__main__':
